-function benutzer_array(int $limit = 100): array
+function benutzer_array(int $limit = 100, ?array $filter = null): array
 {
     $db = datenbank_verbindung();
     if (!$db) {
         return [];
     }

-    $abfrage = $db->prepare('SELECT * FROM benutzer ORDER BY aktiv DESC, gesperrt ASC, id DESC LIMIT :limit');
+    // Für Kompatibilität mit alten Aufrufen: wenn filter nicht gesetzt ist, default auf leeres Array
+    if ($filter === null) {
+        $filter = [];
+    }
+
+    $where = '';
+    $parameter = [];
+
+    // Suchfilter
+    if (isset($filter['q']) && is_string($filter['q'])) {
+        $suchbegriff = trim($filter['q']);
+        if ($suchbegriff !== '') {
+            $where .= ' AND (';
+            $where .= 'benutzername LIKE :suche OR ';
+            $where .= 'anzeigename LIKE :suche OR ';
+            $where .= 'email LIKE :suche OR ';
+            $where .= 'vorname LIKE :suche OR ';
+            $where .= 'nachname LIKE :suche';
+            $where .= ')';
+            $parameter[':suche'] = '%' . $suchbegriff . '%';
+        }
+    }
+
+    // Statusfilter
+    if (isset($filter['status']) && is_string($filter['status'])) {
+        $status = $filter['status'];
+        switch ($status) {
+            case 'aktiv':
+                $where .= ' AND aktiv = 1 AND gesperrt = 0';
+                break;
+            case 'inaktiv':
+                $where .= ' AND aktiv = 0';
+                break;
+            case 'gesperrt':
+                $where .= ' AND gesperrt = 1';
+                break;
+            case 'alle':
+            default:
+                // Keine zusätzliche Bedingung
+                break;
+        }
+    }
+
+    $sql = 'SELECT * FROM benutzer WHERE 1=1' . $where . ' ORDER BY aktiv DESC, gesperrt ASC, id DESC LIMIT :limit';
+    $abfrage = $db->prepare($sql);
     $abfrage->bindValue(':limit', max(1, min($limit, 500)), PDO::PARAM_INT);
+    foreach ($parameter as $key => $value) {
+        $abfrage->bindValue($key, $value);
+    }
     $abfrage->execute();
     return $abfrage->fetchAll() ?: [];
 }
